"""Linguistics-Fragen, Oberthema 2 (Schools of Thought). Viele Lückentexte im Wortlaut des Arbeitsblatts."""
from fr_basis import *
from fr_basis import _txt

R, F = True, False

# ================================================================ structuralism
fam('structuralism', 'lp', 'Knows structuralism, langue and parole',
    lu('Structuralism: This is a school of thought that stems from the work of [[0]] (~1900). In structuralism, linguists are primarily concerned with the abstract language system shared by all members of a speech community, called [[1]], and less so about [[2]], which is about the concrete usage of language by the individual.',
       [['Ferdinand de Saussure', 'Saussure', 'de Saussure', 'F. de Saussure'], ['langue'], ['parole']], 'Saussure – langue – parole.', 2, True, de='Lückentext 2.1 des Arbeitsblatts.'),
    lu('Structuralism stems from the work of [[0]] around [[1]].', [['Ferdinand de Saussure', 'Saussure', 'de Saussure'], ['1900']], '', 1, True, de='Der Strukturalismus geht auf … um … zurück.'),
    lu('[[0]] is the abstract language system shared by a speech community; [[1]] is the concrete usage of language by the individual.', [['langue'], ['parole']], '', 1, True, de='… ist das gemeinsame System; … der konkrete Gebrauch des Einzelnen.'),
    lu('Saussure’s lectures were published after his death by his [[0]] in [[1]] as the “Course in General Linguistics”.', [['students', 'pupils'], ['1916']], '', 2, de='Saussures Vorlesungen wurden nach seinem Tod von seinen … im Jahr … veröffentlicht.'),
    lu('Structuralists are [[0]] concerned with langue and [[1]] so with parole.', [['primarily', 'mainly', 'mostly', 'chiefly'], ['less']], '', 1, de='Strukturalisten beschäftigen sich … mit langue und … mit parole.'),
    zu('Langue or parole?', ['langue', 'parole'], [('the grammar rules of English', 0), ('a text message Anna writes', 1), ('the sound system shared by all speakers', 0), ('a slip of the tongue in a talk', 1), ('the vocabulary of a speech community', 0), ('Ben’s phone call this morning', 1)], 'System = langue, concrete use = parole.', 2, True, de='Langue oder parole?'),
    mc('Who is the founder of structuralism in linguistics?', 'Ferdinand de Saussure', ['Noam Chomsky', 'Roman Jakobson', 'Nikolai Sergeyevich Trubetzkoy'], '', 1, True, de='Wer begründete den Strukturalismus?'),
    mc('Parole is best described as …', 'the concrete usage of language by the individual', ['the abstract system shared by a speech community', 'the innate grammar every child is born with', 'the historical development of a language over the centuries'], '', 1, True, de='Parole beschreibt man am besten als …'),
    blk('True or false?', [('Langue is social: it is shared by the whole speech community.', R), ('Structuralists are mainly interested in parole.', F), ('For Saussure, a sign has value through its differences to other signs.', R), ('Saussure was an American linguist of the 1950s.', F)], '', 2, de='Richtig oder falsch?'),
    kz('Complete the analogy: langue is to parole as the rules of football are to a single …', ['match', 'game'], '', 1, de='Langue verhält sich zu parole wie die Fußballregeln zu einem einzelnen …'),
    rv('Explain the difference between langue and parole and say which one structuralists focus on.', 'Langue is the abstract language system (signs and rules) shared by all members of a speech community. Parole is the concrete usage of language by an individual, e.g. one utterance. Structuralists (Saussure) are primarily concerned with langue.', ['langue = abstract system shared by community', 'parole = concrete individual usage', 'focus of structuralism: langue'], 2, True, de='Erkläre langue und parole und den Schwerpunkt des Strukturalismus.'))

# ================================================================ linguistic sign
_kreis = ('<circle cx="100" cy="125" r="92" style="fill:var(--dg-soft);stroke:var(--dg-b)" stroke-width="2"/>'
          '<line x1="8" y1="125" x2="192" y2="125" style="stroke:var(--dg-b)" stroke-width="2"/>'
          + _txt(100, 75, 'concept: FROG', 13) + _txt(100, 170, '/frɒg/', 20)
          + '<line x1="184" y1="80" x2="214" y2="66" style="stroke:var(--dg-b)" stroke-width="2"/><line x1="184" y1="170" x2="214" y2="184" style="stroke:var(--dg-b)" stroke-width="2"/>')

fam('linguistic-sign', 'zeichen', 'Knows signifié and signifiant',
    bes('Label Saussure’s model of the sign (worksheet 2.1).', [(216, 40, 140, 52, 'signifié (concept)'), (216, 158, 140, 52, 'signifiant (sound image)')], ['referent (real frog)', 'parole'], 'Top: signifié = concept. Bottom: signifiant = sound image.', 2, True, W=360, H=250, deko=_kreis, de='Beschrifte Saussures Zeichenmodell.'),
    lu('signifié (signified) = the [[0]], i.e. that which is signified. [[1]] (signifier) = the sound image, i.e. that which signifies.', [['concept', 'mental concept', 'idea', 'mental idea', 'mental image'], ['signifiant']], 'concept – signifiant.', 2, True, de='Abbildung in 2.1: signifié = das …; … = das Lautbild.'),
    lu('Every linguistic sign has two sides: the [[0]], which is the concept, and the [[1]], which is the sound image.', [['signifié', 'signifie', 'signified'], ['signifiant', 'signifier']], '', 1, True, de='Jedes Zeichen hat zwei Seiten: das … (Konzept) und das … (Lautbild).'),
    lu('For the word “frog”, the sound image /frɒg/ is the [[0]], and the idea of a small green jumping animal is the [[1]].', [['signifiant', 'signifier'], ['signifié', 'signifie', 'signified']], '', 2, True, de='Bei „frog“ ist /frɒg/ das …, die Vorstellung des Tieres das ….'),
    lu('The link between signifiant and signifié is [[0]]: there is no [[1]] connection between sounds and concept.', [['arbitrary'], ['natural']], 'arbitrary – natural.', 2, de='Die Verbindung ist …: Es gibt keine … Verbindung.'),
    mc('What is the signifié of the sign “frog”?', 'the concept or mental idea of a frog', ['the real frog sitting in the pond', 'the sound sequence /frɒg/', 'the written letters f-r-o-g on a page of a book'], 'Concept, not the real animal. · Konzept, nicht das Tier.', 2, True, de='Was ist das signifié von „frog“?'),
    mc('Why do English speakers say “frog”, Germans “Frosch” and French speakers “grenouille”?', 'because the link between sound and concept is arbitrary', ['because frogs sound different in each country', 'because German and French are older languages than English', 'because each language uses a different concept of frog'], '', 2, de='Warum sagt man frog, Frosch und grenouille?'),
    zu('Signifié or signifiant?', ['signifié', 'signifiant'], [('the idea of a tree', 0), ('/triː/', 1), ('that which signifies', 1), ('that which is signified', 0), ('the sound image', 1), ('the concept', 0)], '', 1, True, de='Signifié oder signifiant?'),
    blk('True or false?', [('Signifié and signifiant are like the two sides of a sheet of paper.', R), ('The signifiant is the physical sound wave in the air.', F), ('The sign belongs to langue because it is a convention of the community.', R), ('The real object a word refers to is the signifié.', F)], 'Both sides are mental; the real object is the referent.', 3, de='Richtig oder falsch?'),
    kz('Complete: the signifiant is the sound …', ['image', 'image /frɒg/'], '', 1, True, de='Ergänze: Das signifiant ist das Laut…'),
    rv('Explain Saussure’s model of the linguistic sign with the example “frog”.', 'A linguistic sign consists of two inseparable sides: the signifié (signified), the concept or mental idea of a frog, and the signifiant (signifier), the sound image /frɒg/. The link between them is arbitrary – German uses /frɔʃ/ for the same concept.', ['signifié = concept (idea of frog)', 'signifiant = sound image /frɒg/', 'two inseparable sides', 'link is arbitrary'], 3, True, de='Erkläre Saussures Zeichenmodell am Beispiel „frog“.'))

# ================================================================ Chomsky
fam('formalism-chomsky', 'lad', 'Knows Chomsky, LAD and Universal Grammar',
    lu('Formalism: This school of thought is widely associated with [[0]] work in the 1950s and 1960s. He views every human as being born with a [[1]], i.e. humans are viewed as genetically predisposed to learn language. This is based on the theory of [[2]] which consists of syntactic structures and constraints that are thought to be universal in human languages and, thus, innate.',
       [["Chomsky's", 'Chomsky', "Noam Chomsky's", 'Noam Chomsky', 'Chomskys'], ['language acquisition device', 'language acquisition device (LAD)', 'LAD'], ['Universal Grammar', 'UG', 'universal grammar (UG)']], "Chomsky's – language acquisition device (LAD) – Universal Grammar.", 2, True, de='Lückentext 2.2 des Arbeitsblatts.'),
    lu('Formalism is widely associated with [[0]] work in the [[1]] and 1960s.', [["Chomsky's", 'Chomsky', "Noam Chomsky's", 'Noam Chomsky'], ['1950s', '1950']], '', 1, True, de='Der Formalismus wird mit … Arbeiten der … und 1960er verbunden.'),
    lu('Every human is born with a [[0]] (LAD): humans are genetically [[1]] to learn language.', [['language acquisition device'], ['predisposed', 'prepared', 'programmed']], '', 2, True, de='Jeder Mensch wird mit einem … geboren: Menschen sind genetisch … .'),
    lu('Universal Grammar consists of [[0]] structures and constraints that are thought to be [[1]] in human languages and, thus, [[2]].', [['syntactic'], ['universal'], ['innate', 'inborn']], 'syntactic – universal – innate.', 2, True, de='Universalgrammatik besteht aus … Strukturen und Beschränkungen, die als … und damit … gelten.'),
    lu('Chomsky distinguishes [[0]], the speaker’s unconscious knowledge of grammar, from [[1]], the actual use of language.', [['competence'], ['performance']], '', 2, de='Chomsky unterscheidet … (Wissen) und … (Gebrauch).'),
    mc('What does LAD stand for?', 'language acquisition device', ['language analysis domain', 'linguistic accuracy degree', 'learned acquisition data set'], '', 1, True, de='Wofür steht LAD?'),
    mc('Which observation supports Chomsky’s idea of an innate LAD?', 'a child says “I goed”, a form it never heard', ['children always copy their parents exactly', 'adults learn new languages faster than children', 'all children learn English as their first language'], 'They build rules themselves. · Sie bilden Regeln selbst.', 3, de='Welche Beobachtung stützt Chomskys Idee?'),
    mc('Universal Grammar means that …', 'all human languages share basic innate structures', ['all human languages have identical grammars', 'English grammar is used all over the world', 'grammar must be taught at school before it can be learned'], '', 2, True, de='Universalgrammatik bedeutet, dass …'),
    blk('True or false?', [('Chomsky’s Syntactic Structures appeared in 1957.', R), ('According to Chomsky, language is learned only by imitation.', F), ('Universal Grammar is thought to be innate.', R), ('Chomsky is the founder of structuralism.', F)], '', 2, de='Richtig oder falsch?'),
    kz('Complete: Chomsky’s theory that every human is born with grammatical knowledge is called Universal …', ['Grammar'], '', 1, True, de='Ergänze: Universal …'),
    rv('Explain Chomsky’s idea of the language acquisition device.', 'Chomsky (1950s/60s) claims that every human is born with a language acquisition device: humans are genetically predisposed to learn language. It is based on Universal Grammar, i.e. syntactic structures and constraints that are universal in human languages and therefore innate. That explains why children learn grammar fast and from limited input.', ['every human born with LAD', 'genetically predisposed', 'based on Universal Grammar (universal, innate syntactic structures)', 'children learn fast from limited input'], 3, True, de='Erkläre Chomskys Spracherwerbsapparat.'))

# ================================================================ Jakobson
fam('formalism-jakobson', 'jak', 'Knows Jakobson and the disciplines influenced by formalism',
    li('Formalism (Roman Jakobson 1920s): Name three linguistic disciplines that formalism heavily influenced.', [['phonology'], ['morphology'], ['syntax'], ['semantics'], ['stylistics', 'poetics']], 'phonology, morphology, syntax.', 2, True, n=3, de='Arbeitsblatt 2.3: Nenne drei Disziplinen, die der Formalismus stark beeinflusst hat.'),
    lu('Formalism, represented by [[0]] in the [[1]], heavily influenced phonology, morphology and syntax.', [['Roman Jakobson', 'Jakobson'], ['1920s', '1920']], '', 1, True, de='Formalismus, vertreten durch … in den …'),
    lu('[[0]] studies the sound system, [[1]] the structure of words and [[2]] the structure of sentences.', [['phonology'], ['morphology'], ['syntax']], 'phonology – morphology – syntax.', 1, True, de='… untersucht das Lautsystem, … den Wortbau, … den Satzbau.'),
    lu('In 1926 Jakobson helped found the [[0]] Linguistic Circle together with Nikolai [[1]].', [['Prague'], ['Trubetzkoy', 'Trubetskoy']], '', 3, de='1926 gründete Jakobson mit Nikolai … den … Linguistikkreis.'),
    lu('Jakobson’s most famous contribution to phonology is the theory of [[0]] features, e.g. voiced vs. voiceless in /b/ and /p/.', [['distinctive']], '', 3, de='Jakobsons berühmtester Beitrag: die Theorie der … Merkmale.'),
    zu('Which discipline?', ['phonology', 'morphology', 'syntax'], [('/p/ vs /b/ in pat – bat', 0), ('un-friend-ly', 1), ('word order in “The frog sees the fly.”', 2), ('walk + -ed', 1), ('voiced and voiceless sounds', 0), ('how phrases combine into sentences', 2)], '', 2, True, de='Welche Disziplin?'),
    mc('Which discipline was NOT heavily influenced by formalism?', 'sociolinguistics', ['phonology', 'morphology', 'syntax (sentence structure)'], 'Formalism looks at form, not at society. · Form, nicht Gesellschaft.', 2, True, de='Welche Disziplin wurde NICHT stark vom Formalismus geprägt?'),
    mc('Formalists analyse language mainly by …', 'its form and structure', ['the intentions of the speaker', 'its history and change', 'the social status of speakers'], '', 1, de='Formalisten analysieren Sprache vor allem nach …'),
    blk('True or false?', [('Jakobson belonged to Russian Formalism.', R), ('Jakobson developed the language acquisition device.', F), ('Morphology studies the smallest meaningful parts of words.', R), ('Phonology studies the meaning of sentences.', F)], '', 2, de='Richtig oder falsch?'),
    kz('Which discipline did Jakobson influence most, together with Trubetzkoy?', ['phonology'], '', 2, de='Welche Disziplin prägte Jakobson mit Trubetzkoy am stärksten?'),
    rh('Order the disciplines from the smallest to the largest unit.', ['phonology', 'morphology', 'syntax'], 'sound → word → sentence.', 1, de='Ordne vom kleinsten zur größten Einheit.'))

# ================================================================ overview
fam('schools-overview', 'ueber', 'Assigns names, dates and key terms',
    zu('Saussure, Jakobson or Chomsky?', ['Saussure', 'Jakobson', 'Chomsky'], [('langue and parole', 0), ('language acquisition device', 2), ('Prague Linguistic Circle', 1), ('signifié and signifiant', 0), ('Universal Grammar', 2), ('distinctive features', 1), ('~1900', 0), ('1950s/60s', 2)], '', 2, True, de='Saussure, Jakobson oder Chomsky?'),
    rh('Put the linguists in chronological order.', ['Saussure (~1900)', 'Jakobson (1920s)', 'Chomsky (1950s/60s)'], '', 1, True, de='Bringe die Linguisten in zeitliche Reihenfolge.'),
    lu('[[0]] stands for structuralism, while Jakobson and [[1]] stand for formalism.', [['Saussure', 'Ferdinand de Saussure'], ['Chomsky', 'Noam Chomsky']], '', 1, True, de='… steht für Strukturalismus, Jakobson und … für Formalismus.'),
    lu('Saussure’s pair langue/parole roughly corresponds to Chomsky’s pair [[0]]/[[1]].', [['competence'], ['performance']], '', 2, de='Saussures langue/parole entspricht in etwa Chomskys …/….'),
    mc('What is the main difference between langue and competence?', 'langue is social, competence is in each speaker’s mind', ['langue is innate, competence is learned at school', 'langue is spoken, competence is only written', 'there is no real difference at all between the two terms'], '', 3, de='Hauptunterschied zwischen langue und Kompetenz?'),
    mc('Which term belongs to structuralism?', 'signifiant', ['Universal Grammar', 'language acquisition device', 'distinctive features'], '', 1, True, de='Welcher Begriff gehört zum Strukturalismus?'),
    blk('True or false?', [('Saussure’s work is older than Chomsky’s.', R), ('Jakobson worked in the 1950s and 1960s.', F), ('All three focus on the language system rather than on single conversations.', R), ('Chomsky developed the model of signifié and signifiant.', F)], '', 1, de='Richtig oder falsch?'),
    kz('Which school of thought did Ferdinand de Saussure found?', ['structuralism', 'structural linguistics'], '', 1, True, de='Welche Denkschule begründete Saussure?'),
    rv('Compare structuralism and formalism (Chomsky): who, when, key idea.', 'Structuralism: Ferdinand de Saussure, ~1900; language as an abstract system of signs (langue) shared by a speech community, studied rather than parole. Formalism: Noam Chomsky, 1950s/60s; humans are born with a language acquisition device based on innate Universal Grammar.', ['Saussure ~1900, langue/parole', 'Chomsky 1950s/60s', 'LAD and Universal Grammar', 'both focus on the system'], 3, True, de='Vergleiche Strukturalismus und Formalismus (Chomsky).'))
